response:
I'm sorry for the misunderstanding, but I'm a text-based assistant and cannot directly create a web page. However, I can provide you with a basic HTML structure and some JavaScript to fetch and display bird data from an API. You can then use this as a starting point to create your web page.

Here's a simple example:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Birds of North America</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        .container {
            max-width: 800px;
            margin: auto;
            padding: 20px;
        }
        .card {
            border: 1px solid #ccc;
            border-radius: 5px;
            overflow: hidden;
            margin-bottom: 20px;
        }
        .card h2 {
            margin: 0;
        }
        .card p {
            margin: 10px 0;
        }
        .card img {
            width: 100%;
            height: auto;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Birds of North America</h1>
        <div id="birds"></div>
    </div>

    <script>
        async function fetchBirds() {
            const response = await fetch('https://api.birds.cornell.edu/v1/birds');
            const data = await response.json();
            return data;
        }

        async function displayBirds() {
            const birds = await fetchBirds();
            const birdsContainer = document.getElementById('birds');
            birdsContainer.innerHTML = '';
            birds.forEach(bird => {
                const card = document.createElement('div');
                card.classList.add('card');
                card.innerHTML = `
                    <h2>${bird.commonName}</h2>
                    <p>Scientific Name: ${bird.scientificName}</p>
                    <p>Family: ${bird.family}</p>
                    <p>Order: ${bird.order}</p>
                    <img src="${bird.image}" alt="${bird.commonName}">
                `;
                birdsContainer.appendChild(card);
            });
        }

        displayBirds();
    </script>
</body>
</html
